// Picks the vendored Botan amalgamation for this target (ADR-0001). Each <target>/ folder is
// generated by scripts/build_botan.sh <target> and excluded from SwiftPM's source list, so only
// this file is compiled.
#if defined(__APPLE__) && defined(__aarch64__)
  #include "macos-arm64/botan_all.cpp"
#elif defined(__linux__) && defined(__x86_64__)
  #include "linux-x86_64/botan_all.cpp"
#else
  #error "no vendored Botan amalgamation for this target; see scripts/build_botan.sh"
#endif
